/* Morale gameplay: temporary match ratings, persistent locker-room consequences. */
let moraleMatch=null;
function moraleTier(score){return score>=90?'Ecstatic':score>=70?'Content':score>=40?'Discontent':'Angry'}
function moraleSystem(){return state.moraleSystem??={captains:{},events:{}}}
function moraleCaptain(club){return club?teamCaptain(club):null}
const moraleRawDetails=moraleDetails;
// Captains no longer impose a morale floor; leadership acts through the per-game change in updateMoraleAfterGame.
moraleDetails=function(p,club){const m=moraleRawDetails(p,club);m.label=moraleTier(m.score);return m};
// Retire the previous blanket bonus; the match wrapper supplies tier-specific ratings once.
moraleBonus=()=>0;
teamChemistry=function(club){const score=Math.round(club.roster.reduce((s,p)=>s+moraleDetails(p,club).score,0)/Math.max(1,club.roster.length));return {score,modifier:0}};
function moraleMatchScore(p){return moraleMatch?.scores.get(p.id)??70}
function moraleAttributeValue(value,key,score){if(!['oiq','diq','pss','per'].includes(key))return value;return ratingLimit(Math.round(value*(score>=90?1.01:score<40?.98:score<70?.99:1)))}
const moraleSimBefore=simulateAttributeGame;
simulateAttributeGame=function(a,b,...args){const prior=moraleMatch,clubs=[state.teams[a],state.teams[b]],players=[...new Set(clubs.flatMap(c=>c.roster))],originals=new Map();moraleMatch={scores:new Map(),chemistry:new Map(clubs.map(c=>[c.id,teamChemistry(c).score]))};try{for(const club of clubs)for(const p of club.roster){withBasketballAttributes(p);const score=moraleDetails(p,club).score;moraleMatch.scores.set(p.id,score);originals.set(p,p.attributes);p.attributes=Object.fromEntries(Object.entries(p.attributes).map(([k,v])=>[k,moraleAttributeValue(v,k,score)]))}return moraleSimBefore(a,b,...args)}finally{for(const [p,attributes]of originals)p.attributes=attributes;moraleMatch=prior}};
function moraleFoulFactor(p){return moraleMatchScore(p)<40&&hasTrait(p,'fiery')?1.05:1}
function moraleAssistChance(chance,club){return Math.min(1,chance*(moraleMatch?.chemistry.get(club.id)>80?1.02:1))}
function moraleClutchBonus(p,minute,margin){return moraleMatchScore(p)>=90&&minute>=gameMinutes()-leagueRules().periodMinutes&&Math.abs(margin)<=8?.005:0}
const moraleReboundBefore=reboundPlayerWeight;reboundPlayerWeight=function(p){return moraleReboundBefore(p)*(moraleMatchScore(p)>=90?1.02:1)};
// Contract willingness is supplied by the shared persistent dissatisfaction model.
const moraleTradeValueBefore=tradePlayerValue;tradePlayerValue=function(p,...args){return moraleTradeValueBefore(p,...args)*(p.dissatisfaction?.active?.visibility==='public'?.95:1)};
function moraleAdjust(p,amount){p.moraleAdjustment=Math.max(-100,Math.min(100,(p.moraleAdjustment||0)+amount))}
function moraleAnnounce(club,subject,text){say(text+' ('+club.abbr+')');if(club.id===controlledTeamId())addGMMessage('Morale','Locker room',subject,text)}
updateMoraleAfterGame=function(club,won){for(const p of club.roster){const d=dissatisfactionRecord(p,club),g=state.history[0],key=state.year+':'+(g?.day??state.day)+':'+(g?.stage??'game')+':'+club.id+':'+(club.w+club.l);if(d.lastGame===key)continue;const lead=leadershipMoraleChange(p,club,performanceMoraleChange(p,club,won),.03),change=Math.round(Math.max(-4,Math.min(4,lead.raw))*.5-(p.moraleAdjustment||0)*lead.decay);moraleAdjust(p,change);const m=performanceMood(p);if(m)m.lastChange=change;dissatisfactionAfterGame(p,club,moraleDetails(p,club).score);}};
function moraleNarrative(club,kind,p){if(kind==='role'||kind==='contract'){const d=dissatisfactionRecord(p,club),stamp=dissatisfactionStamp();if(d.history.some(e=>e.type==='concern'&&stamp-e.stamp<30))return;dissatisfactionHistory(d,'concern',{reason:kind});if(kind==='role'){d.response='frustrated';moraleAdjust(p,-2);}else moraleAdjust(p,-1);dissatisfactionNotify(p,club,p.name+(kind==='role'?' raised concerns about playing time.':' is weighing the next contract.')+(d.active?' The existing trade request remains unresolved.':' No trade request has been made.'));}if(kind==='media'){moraleAdjust(p,-2);moraleAnnounce(club,'Media scrutiny',p.name+' faced questions about the team’s recent results.')}if(kind==='dinner'){club.roster.forEach(q=>moraleAdjust(q,5));moraleAnnounce(club,'The bounce back','Following a team dinner organized by '+p.name+', every player received a +5 morale adjustment.')}}
function moraleEventDay(){const store=moraleSystem();for(const club of state.teams){const key=state.year+':'+Math.floor(state.day/7);if(state.day<1||state.day%7||store.events[club.id]===key)continue;store.events[club.id]=key;if(Math.random()>=.25)continue;const choices=[];for(const p of club.roster){const m=moraleDetails(p,club).score;if(club.roster.indexOf(p)>=leagueRules().courtPlayers&&playerMinutes(p,club)<expectedPlayerRole(p)[1]-5&&m<70)choices.push(['role',p]);if((p.contractThrough??state.year)<=state.year&&m<70)choices.push(['contract',p]);if(m<40&&club.l>club.w)choices.push(['media',p]);if(hasTrait(p,'leader')&&m>=80||leadershipCaptains(club).includes(p.id)&&playerLeadership(p)>=65&&m>=65)choices.push(['dinner',p]);}if(choices.length){const [kind,p]=choices[Math.floor(Math.random()*choices.length)];moraleNarrative(club,kind,p)}}}
const moraleDayBefore=ownerDay;ownerDay=function(...args){const result=moraleDayBefore(...args);moraleEventDay();return result};
// Retained for older callers: commissioner mode appoints directly; otherwise this is a recommendation to the coach.
async function setTeamCaptain(value){return state.commissioner?.enabled?commissionerSetCaptain(controlledTeamId(),'captain',value):recommendCaptain(value)}
const moraleManagementBefore=teamManagementView;teamManagementView=function(){const body=moraleManagementBefore();const club=state.teams.find(t=>t.id===managedTeamId);if(!club||managedTeamId!==controlledTeamId()&&!state.commissioner?.enabled)return body;return body+leadershipPanel(club)};
moraleProfile=function(ctx){const m=moraleDetails(ctx.p,ctx.club);return personalityCards(ctx.p)+moraleBaseOverview(ctx)+playerCard('MORALE EFFECTS',`<p>${m.label}: confidence can modestly affect decision-making and defensive focus (at most 2% on selected effective ratings). Base attributes stay unchanged. Low morale does not force missed games, bad shots, stalled development or a trade request.</p>${ctx.own?`<button onclick="holdMoraleMeeting(${ctx.p.id})" ${moraleStamp()-(ctx.p.lastTalk??-10000000)<7?'disabled':''}>Coach conversation</button>`:''}`)};
const moraleValidateBefore=validateCareerData;validateCareerData=function(raw){const result=moraleValidateBefore(raw);if(raw.moraleSystem!==undefined){const m=raw.moraleSystem;if(!m||!m.captains||!m.events||typeof m.captains!=='object'||typeof m.events!=='object'||Array.isArray(m.captains)||Array.isArray(m.events))throw Error('Invalid morale system');const captains={},events={};for(const [key,id]of Object.entries(m.captains)){if(!/^\d+$/.test(key)||!result.teams.some(t=>t.id===Number(key))||!Number.isInteger(id)||id<0||id>10000000)throw Error('Invalid captain');captains[key]=id}for(const [key,stamp]of Object.entries(m.events)){if(!/^\d+$/.test(key)||!result.teams.some(t=>t.id===Number(key))||typeof stamp!=='string'||!/^\d{4,5}:\d{1,3}$/.test(stamp))throw Error('Invalid morale event date');events[key]=stamp}result.moraleSystem={captains,events}}return result};
